const raw = $input.first().json;
const body = raw.body || raw;
function torontoNow() {
  return new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Toronto' }));
}
function minutesUntilNextMorningOpen(openHour) {
  const now = torontoNow();
  const target = new Date(now);
  target.setSeconds(0, 0);
  const day = now.getDay();
  const hour = now.getHours();
  const isBiz = (d) => d >= 1 && d <= 6;
  const oh = parseInt(openHour || 9, 10);
  if (isBiz(day) && hour < oh) {
    target.setHours(oh, 0, 0, 0);
  } else {
    let c = new Date(now);
    c.setDate(c.getDate() + 1);
    c.setHours(oh, 0, 0, 0);
    while (!isBiz(c.getDay())) c.setDate(c.getDate() + 1);
    target.setTime(c.getTime());
  }
  let m = Math.round((target - now) / 60000);
  return m < 1 ? 1 : m;
}
const pipeline = (body.pipeline || 'immo').toLowerCase();
const openHour = pipeline === 'energie' ? 8 : 9;
return [{ json: {
  ...body,
  pipeline,
  open_hour: openHour,
  wait_minutes: minutesUntilNextMorningOpen(openHour),
  scheduled_at: new Date().toISOString()
}}];

const b = $('2 Calc attente matin').first().json;
const pipeline = b.pipeline;
let lead = {};
try {
  if (pipeline === 'immo') {
    lead = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://intellixcrm.com/api/immo/lead/${b.lead_id}`,
      headers: { 'X-Immo-Webhook-Token': '{{META_IMMO_WEBHOOK_TOKEN}}' },
      json: true,
    });
  } else if (pipeline === 'haidly') {
    lead = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://intellixcrm.com/api/haidly/lead/${b.lead_id}`,
      headers: { 'X-Haidly-Webhook-Token': '{{HAIDLY_WEBHOOK_TOKEN}}' },
      json: true,
    });
  } else if (pipeline === 'energie') {
    lead = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://intellixcrm.com/api/energie/lead/${b.lead_id}`,
      headers: { 'X-Energie-Webhook-Token': '{{ENERGIE_WEBHOOK_TOKEN}}' },
      json: true,
    });
  }
} catch (e) {}
const dnc = lead.do_not_call || lead.immo_do_not_call || lead.haidly_do_not_call || lead.energie_do_not_call;
const nowStr = new Date().toLocaleString('en-US', { timeZone: 'America/Toronto' });
const h = new Date(nowStr).getHours();
const day = new Date(nowStr).getDay();
const endH = pipeline === 'energie' ? 20 : 19;
const startH = pipeline === 'energie' ? 8 : 9;
const canCall = !dnc && day >= 1 && day <= 6 && h >= startH && h < endH;
return [{ json: { ...b, ...lead, can_call: canCall, skip_reason: dnc ? 'dnc' : (!canCall ? 'outside_hours' : '') } }];

const b = $input.first().json;
const apiKey = '{{ELEVENLABS_API_KEY}}';
const pipeline = b.pipeline;
let agentId = b.agent_id || '';
let phId = b.elevenlabs_phone_number_id || '';
if (pipeline === 'immo') {
  agentId = agentId || b.elevenlabs_agent_id_immo || '';
} else if (pipeline === 'haidly') {
  agentId = agentId || b.elevenlabs_agent_id_haidly || '';
} else if (pipeline === 'energie') {
  agentId = agentId || b.elevenlabs_agent_id_energie || '';
}
if (!agentId || !phId || !b.phone) {
  return [{ json: { ...b, call_skipped: true, reason: 'missing_ids' } }];
}
const first = (b.first_name || b.lead_name || 'there').split(' ')[0];
let dyn = b.dynamic_variables || {};
if (pipeline === 'immo') {
  dyn = { lead_name: first, property_address: b.full_address || b.property_address || '', selling_timeline: b.selling_timeline || '', lead_id_odoo: String(b.lead_id || ''), ...dyn };
} else if (pipeline === 'haidly') {
  dyn = { lead_name: first, project_type: b.project_type || 'multi', city: b.city || '', budget_range: b.budget_range || '', property_type: b.property_type || '', lead_id_odoo: String(b.lead_id || ''), ...dyn };
} else if (pipeline === 'energie') {
  dyn = { lead_name: first, lead_site: b.energie_site_source || b.site || '', lead_city: b.city || b.lead_city || '', current_heating: b.current_heating || '', project_type: b.project_type || '', lead_id_odoo: String(b.lead_id || ''), ...dyn };
}
const res = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.elevenlabs.io/v1/convai/twilio/outbound-call',
  headers: { 'xi-api-key': apiKey, 'Content-Type': 'application/json' },
  body: {
    agent_id: agentId,
    agent_phone_number_id: phId,
    to_number: b.phone,
    telephony_call_config: { ringing_timeout_secs: 25 },
    conversation_initiation_client_data: { dynamic_variables: dyn }
  },
  json: true,
});
return [{ json: { ...b, ...res, call_started: true, morning_call: true } }];

const b = $('6 Appel matin ElevenLabs').first().json;
const pipeline = b.pipeline;
if (!b.lead_id) return [{ json: b }];
if (pipeline === 'immo') {
  await this.helpers.httpRequest({ method: 'POST', url: 'https://intellixcrm.com/api/immo/lead/update', headers: { 'X-Immo-Webhook-Token': '{{META_IMMO_WEBHOOK_TOKEN}}', 'Content-Type': 'application/json' }, body: { lead_id: b.lead_id, increment_call_attempt: true, next_action: 'Appel matin J+0 (hors heures)' }, json: true });
} else if (pipeline === 'haidly') {
  await this.helpers.httpRequest({ method: 'POST', url: 'https://intellixcrm.com/api/haidly/lead/update', headers: { 'X-Haidly-Webhook-Token': '{{HAIDLY_WEBHOOK_TOKEN}}', 'Content-Type': 'application/json' }, body: { lead_id: b.lead_id, increment_call_attempt: true }, json: true });
} else if (pipeline === 'energie') {
  await this.helpers.httpRequest({ method: 'POST', url: 'https://intellixcrm.com/api/energie/lead/update', headers: { 'X-Energie-Webhook-Token': '{{ENERGIE_WEBHOOK_TOKEN}}', 'Content-Type': 'application/json' }, body: { lead_id: b.lead_id, increment_call_attempt: true }, json: true });
}
return [{ json: b }];

const b = $('2 Calc attente matin').first().json;
const called = $('6 Appel matin ElevenLabs').first()?.json || {};
const pipeline = b.pipeline;
const nurtureUrl = {
  immo: '{{N8N_WEBHOOK_BASE}}/webhook/immo-nurture-start',
  haidly: '{{N8N_WEBHOOK_BASE}}/webhook/haidly-nurture-start',
  energie: '{{N8N_WEBHOOK_BASE}}/webhook/energie-nurture-start'
}[pipeline];
if (!nurtureUrl || pipeline === 'energie') return [{ json: { ...b, nurture_skipped: pipeline === 'energie' } }];
const payload = {
  lead_id: b.lead_id,
  phone: b.phone,
  first_name: b.first_name,
  score: 'warm',
  call_answered: false,
  skip_initial_call: false,
  morning_call_done: true,
  total_call_attempts: 1
};
if (pipeline === 'immo') {
  payload.full_address = b.full_address || b.property_address || '';
} else if (pipeline === 'haidly') {
  payload.project_type = b.project_type;
  payload.city = b.city;
}
try {
  await this.helpers.httpRequest({ method: 'POST', url: nurtureUrl, headers: { 'Content-Type': 'application/json' }, body: payload, json: true });
} catch (e) {}
return [{ json: { ...b, nurture_started: true } }];
